622:     fn handle_play(&mut self, packet: &Packet, writer: &mut impl Write) -> io::Result<()> {
623:         let decoded = play::Serverbound::decode(packet.id, &packet.data);
624:         let valid = match decoded {
625:             Ok(play::Serverbound::TeleportAcknowledged(ack)) => {
626:                 if let Some(pending) = self.pending_teleport {
627:                     if ack.id == pending.pose.id
628:                         && ack.position == pending.pose.position.map(f64::to_bits)
629:                         && ack.rotation == pending.pose.rotation.map(f32::to_bits)
630:                     {
631:                         if pending.kind == TeleportKind::Initial {
632:                             self.teleport_confirmed = true;
633:                         }
634:                         self.pending_teleport = None;
635:                         true
636:                     } else {
637:                         false
638:                     }
639:                 } else {
640:                     false
641:                 }
642:             }
643:             Ok(play::Serverbound::PlayerLoaded) => {
644:                 if !self.player_loaded {
645:                     self.player_loaded = true;
646:                     true
647:                 } else {
648:                     false
649:                 }
650:             }
651:             Ok(play::Serverbound::ChatSession | play::Serverbound::ChunkBatchReceived) => true,
652:             // This packet describes client movement cadence, not server loading time.
653:             Ok(play::Serverbound::ClientTickEnd) => true,
654:             Ok(play::Serverbound::Abilities { flying }) => {
655:                 self.flying = !self.dead && flying && matches!(self.game_mode, 1 | 3);
656:                 self.send_mode_state(writer)?;
657:                 true
658:             }
659:             Ok(play::Serverbound::KeepAlive(id)) => {
660:                 if self.keepalive.is_some_and(|(expected, _)| id == expected) {
661:                     self.record_keepalive_rtt();
662:                     self.keepalive = None;
663:                     true
664:                 } else {
665:                     false
666:                 }
667:             }
668:             Ok(play::Serverbound::ClientInformation(info)) => {
669:                 self.chunk_radius = i32::from(info.view_distance)
670:                     .clamp(1, rusty_mines::vanilla_world::MAX_RENDER_DISTANCE);
671:                 self.pending_chunk_center = Some(self.chunk_center);
672:                 self.client_information = Some(info);
673:                 true
674:             }
675:             Ok(play::Serverbound::PluginMessage { channel, data }) => {
676:                 if channel == "minecraft:brand" || channel == "brand" {
677:                     match configuration::decode_brand(&data) {
678:                         Ok(brand) => {
679:                             self.client_brand = Some(brand);
680:                             true
681:                         }
682:                         Err(_) => false,
683:                     }
684:                 } else {
685:                     // Brand is the only supported Play plugin channel. Unknown
686:                     // channels are bounded by the codec and intentionally ignored.
687:                     true
688:                 }
689:             }
690:             Ok(play::Serverbound::Movement(_)) if self.dead => true,
691:             Ok(play::Serverbound::Movement(movement)) if self.pending_teleport.is_some() => {
692:                 let _ = movement;
693:                 true
694:             }
695:             Ok(play::Serverbound::Movement(movement)) => {
696:                 let old_position = self.player_position;
697:                 let mut valid = true;
698:                 let mut corrected = false;
699:                 if let Some(position) = movement.position {
700:                     let border = f64::from(rusty_mines::vanilla_world::WORLD_BORDER)
701:                         - f64::from(rusty_mines::vanilla_world::MAX_RENDER_DISTANCE * 16);
702:                     valid = [0_usize, 2]
703:                         .into_iter()
704:                         .all(|axis| (position[axis] - old_position[axis]).abs() <= 16.0);
705:                     // The server owns vertical position. Only authorized flight may
706:                     // accept a client vertical coordinate; otherwise gravity advances it.
707:                     if self.flying && matches!(self.game_mode, 1 | 3) {
708:                         let delta = position[1] - old_position[1];
709:                         if delta.abs() > 16.0 {
710:                             valid = false;
711:                         }
712:                     }
713:                     if valid {
714:                         for axis in [0_usize, 2] {
715:                             self.player_position[axis] = position[axis].clamp(-border, border);
716:                             corrected |= self.player_position[axis] != position[axis];
717:                         }
718:                         if self.flying && matches!(self.game_mode, 1 | 3) {
719:                             self.player_position[1] = position[1].clamp(-64.0, 320.0);
720:                             corrected |= self.player_position[1] != position[1];
721:                             self.vertical_velocity = 0.0;
722:                         }
723:                         self.pending_chunk_center = Some((
724:                             (self.player_position[0].floor() as i32).div_euclid(16),
725:                             (self.player_position[2].floor() as i32).div_euclid(16),
726:                         ));
727:                     }
728:                 }
729:                 if valid {
730:                     // Client ground/collision bits are advisory only.
731:                     let _ = (movement.on_ground, movement.horizontal_collision);
732:                     if let Some(rotation) = movement.rotation {
733:                         self.player_rotation = rotation;
734:                     }
735:                     if let Err(error) = self.publish_authoritative_pose() {
736:                         if error.kind() != io::ErrorKind::Unsupported {
737:                             return self.disconnect_play(
738:                                 writer,
739:                                 "Backend player state unavailable; reconnect",
740:                             );
741:                         }
742:                     }
743:                     if !self.flying && self.game_mode != 3 {
744:                         self.simulate_vertical((self.clock)(), writer)?;
745:                     }
746:                     if corrected {
747:                         self.send_teleport(TeleportKind::Correction, writer)?;
748:                     }
749:                 }
750:                 if !valid {
751:                     self.send_teleport(TeleportKind::Correction, writer)?;
752:                 }
753:                 true
754:             }
755:             Ok(play::Serverbound::ChatMessage(message)) => {
756:                 let Some(session) = self.backend_session.filter(|_| self.play_confirmed) else {
757:                     return self.disconnect_play(
758:                         writer,
759:                         "Player chat requires an active backend Play session",
760:                     );
761:                 };
762:                 if self.chat_pending.is_some() {
763:                     self.system_message(writer, "A player chat request is still pending.")?;
764:                 } else {
765:                     match self.backend.chat_send(session, message) {
766:                         Ok(receiver) => {
767:                             self.chat_pending = Some(PendingChat {
768:                                 receiver,
769:                                 deadline: (self.clock)() + Duration::from_secs(3),
770:                             })
771:                         }
772:                         Err(error) => {
773:                             self.system_message(writer, &format!("Chat unavailable: {error}"))?
774:                         }
775:                     }
776:                 }
777:                 true
778:             }
779:             Ok(play::Serverbound::ChatCommand(command)) => {
780:                 let parts: Vec<_> = command.split_whitespace().collect();
781:                 if let ["storage", uuid] = parts.as_slice() {
782:                     if let Ok(uuid) = uuid::Uuid::parse_str(uuid) {
783:                         self.queue_inventory(3, uuid.as_bytes().to_vec(), None, writer)?;
784:                     } else {
785:                         self.system_message(writer, "Usage: /storage <authorized storage UUID>")?;
786:                     }
787:                 } else if parts == ["inventory"] {
788:                     let menu = self
789:                         .inventory_snapshot
790:                         .as_ref()
791:                         .map_or(0, |snapshot| snapshot.menu_id);
792:                     let mut fields = Vec::new();
793:                     rusty_mines_inventory::wire::put_int(&mut fields, menu);
794:                     self.queue_inventory(4, fields, None, writer)?;
795:                 } else if parts == ["help"] {
796:                     self.system_message(writer, "Commands: /help, /inventory, /storage <UUID>. Player chat is unsigned and may be disabled by the server.")?;
797:                 } else {
798:                     self.system_message(writer, "Unknown command. Use /help.")?;
799:                 }
800:                 true
801:             }
802:             Ok(play::Serverbound::SignedChatMessage(_))
803:             | Ok(play::Serverbound::SignedChatCommand(_)) => {
804:                 self.system_message(
805:                     writer,
806:                     "Signed chat is not verified or accepted; use ordinary unsigned chat.",
807:                 )?;
808:                 true
809:             }
810:             Ok(play::Serverbound::ChatAcknowledgement) => true,
811:             Ok(play::Serverbound::ClientStatus(0)) if self.dead => {
812:                 if self.pending_player_state.is_none() {
813:                     let Some(session) = self.backend_session else {
814:                         if !self.backend.requires_persistent_player_state() {
815:                             self.respawn(
816:                                 crate::gateway::GatewayPlayerState {
817:                                     mode: if self.game_mode == 2 {
818:                                         crate::module_bindings::GameMode::Adventure
819:                                     } else {
820:                                         crate::module_bindings::GameMode::Survival
821:                                     },
822:                                     health: 20,
823:                                     food: self.food.clamp(0, 20) as u8,
824:                                     dead: false,
825:                                     revision: 0,
826:                                     respawn_revision: Some(0),
827:                                     state_owner: None,
828:                                 },
829:                                 writer,
830:                             )?;
831:                             return Ok(());
832:                         }
833:                         return Err(io::Error::other("Respawn requires active backend Play"));
834:                     };
835:                     let request = match self.backend_session {
836:                         Some(session) => self.backend.player_respawn_request(session),
837:                         None => unreachable!("session was checked above"),
838:                     };
839:                     match request {
840:                         Ok(receiver) => {
841:                             let mut expected =
842:                                 self.backend.player_state(session)?.ok_or_else(|| {
843:                                     io::Error::other(
844:                                         "Persistent player state unavailable; reconnect",
845:                                     )
846:                                 })?;
847:                             expected.health = 20;
848:                             expected.dead = false;
849:                             expected.revision = expected.revision.saturating_add(1);
850:                             expected.respawn_revision = Some(expected.revision);
851:                             if expected.state_owner.is_none() {
852:                                 self.system_message(writer, "Persistent player state ownership is unavailable; respawn refused.")?;
853:                                 return Ok(());
854:                             }
855:                             if self.pending_player_state.is_some() {
856:                                 return Ok(());
857:                             }
858:                             self.pending_player_state = Some(PendingPlayerState {
859:                                 receiver,
860:                                 expected,
861:                                 deadline: (self.clock)() + Duration::from_secs(3),
862:                                 accepted: false,
863:                                 respawn: true,
864:                             });
865:                         }
866:                         Err(error) => {
867:                             self.system_message(writer, &format!("Respawn unavailable: {error}"))?;
868:                         }
869:                     }
870:                 }
871:                 true
872:             }
873:             Ok(play::Serverbound::ClientStatus(_)) => true,
874:             Ok(play::Serverbound::ChangeGameMode(value)) => {
875:                 if self.dead {
876:                     self.send_mode_state(writer)?;
877:                     return Ok(());
878:                 }
879:                 if self.pending_mode.is_some() {
880:                     self.send_mode_state(writer)?;
881:                     return Ok(());
882:                 }
883:                 let Some(session) = self.backend_session else {
884:                     return self.disconnect_play(writer, "Mode changes require backend Play");
885:                 };
886:                 let mode = match value {
887:                     0 => crate::module_bindings::GameMode::Survival,
888:                     2 => crate::module_bindings::GameMode::Adventure,
889:                     _ => {
890:                         self.send_mode_state(writer)?;
891:                         return Ok(());
892:                     }
893:                 };
894:                 match self.backend.change_game_mode(session, mode) {
895:                     Ok(receiver) => {
896:                         self.pending_mode = Some((
897:                             receiver,
898:                             value as u8,
899:                             (self.clock)() + Duration::from_secs(3),
900:                             false,
901:                         ))
902:                     }
903:                     Err(error) => {
904:                         self.system_message(writer, &format!("Mode change unavailable: {error}"))?;
905:                         self.send_mode_state(writer)?;
906:                     }
907:                 }
908:                 true
909:             }
910:             Ok(play::Serverbound::PlayerInput(flags)) => {
911:                 self.input_flags = if self.dead { 0 } else { flags };
912:                 true
913:             }
914:             Ok(play::Serverbound::HeldSlot(slot)) => {
915:                 if self.dead {
916:                     self.inventory_resync = true;
917:                     self.refresh_inventory(writer)?;
918:                 } else if self.inventory_snapshot.is_some() {
919:                     let mut fields = Vec::new();
920:                     rusty_mines_inventory::wire::put_int(&mut fields, i32::from(slot));
921:                     self.queue_inventory(0, fields, None, writer)?;
922:                 } else {
923:                     self.held_slot = slot;
924:                 }
925:                 true
926:             }
927:             Ok(play::Serverbound::PlayerCommand { action, .. }) => {
928:                 if !self.dead {
929:                     match action {
930:                         1 => self.sprinting = true,
931:                         2 => self.sprinting = false,
932:                         _ => {}
933:                     }
934:                 }
935:                 true
936:             }
937:             Ok(play::Serverbound::PlayerAction {
938:                 status,
939:                 position,
940:                 sequence,
941:                 ..
942:             }) => {
943:                 if self.dead {
944:                     self.correct_block(writer, position)?;
945:                     play::Clientbound::BlockAcknowledgement(sequence).write(writer)?;
946:                 } else if status == 2 {
947:                     self.queue_block_action(sequence, position, false, writer)?;
948:                 } else if status == 0 || status == 1 {
949:                     self.correct_block(writer, position)?;
950:                     play::Clientbound::BlockAcknowledgement(sequence).write(writer)?;
951:                 } else if status == 3 || status == 4 {
952:                     self.inventory_resync = true;
953:                     self.refresh_inventory(writer)?;
954:                 } else if status == 6 {
955:                     self.queue_inventory(6, Vec::new(), None, writer)?;
956:                 } else {
957:                     play::Clientbound::BlockAcknowledgement(sequence).write(writer)?;
958:                 }
959:                 true
960:             }
961:             Ok(play::Serverbound::UseItemOn {
962:                 position,
963:                 face,
964:                 sequence,
965:                 ..
966:             }) => {
967:                 let target = position.adjacent(face);
968:                 if self.dead {
969:                     self.correct_block(writer, position)?;
970:                     self.correct_block(writer, target)?;
971:                     play::Clientbound::BlockAcknowledgement(sequence).write(writer)?;
972:                     return self.confirm_play(writer);
973:                 }
974:                 let held = self
975:                     .inventory_snapshot
976:                     .as_ref()
977:                     .and_then(|snapshot| {
978:                         rusty_mines_inventory::model::decode_slots(
979:                             &snapshot.slots,
980:                             if snapshot.menu_id == 0 { 46 } else { 63 },
981:                         )
982:                         .ok()
983:                     })
984:                     .and_then(|slots| {
985:                         slots
986:                             .get(36 + usize::from(self.held_slot.max(0) as u8))
987:                             .cloned()
988:                     });
989:                 let stone = rusty_mines_inventory::model::item_id("minecraft:stone").ok();
990:                 if held
991:                     .as_ref()
992:                     .is_some_and(|stack| stack.count > 0 && Some(stack.item) == stone)
993:                 {
994:                     self.queue_block_action(sequence, target, true, writer)?;
995:                 } else {
996:                     self.correct_block(writer, position)?;
997:                     self.correct_block(writer, target)?;
998:                     play::Clientbound::BlockAcknowledgement(sequence).write(writer)?;
999:                 }
1000:                 true
1001:             }
1002:             Ok(play::Serverbound::UseItem {
1003:                 sequence, rotation, ..
1004:             }) => {
1005:                 if !self.dead {
1006:                     self.player_rotation = rotation;
1007:                 }
1008:                 play::Clientbound::BlockAcknowledgement(sequence).write(writer)?;
1009:                 true
1010:             }
1011:             Ok(play::Serverbound::CreativeSlot { slot, stack }) => {
1012:                 if self.dead {
1013:                     self.inventory_resync = true;
1014:                     self.refresh_inventory(writer)?;
1015:                 } else {
1016:                     let mut fields = Vec::new();
1017:                     rusty_mines_inventory::wire::put_int(&mut fields, i32::from(slot));
1018:                     fields.extend(stack.trusted_bytes());
1019:                     self.queue_inventory(1, fields, None, writer)?;
1020:                 }
1021:                 true
1022:             }
1023:             Ok(play::Serverbound::InventoryClick(click)) => {
1024:                 if self.dead {
1025:                     self.inventory_resync = true;
1026:                     self.refresh_inventory(writer)?;
1027:                     return self.confirm_play(writer);
1028:                 }
1029:                 let stale = self.inventory_snapshot.as_ref().is_none_or(|snapshot| {
1030:                     snapshot.revision != click.revision || snapshot.menu_id != click.menu
1031:                 });
1032:                 if stale {
1033:                     self.inventory_resync = true;
1034:                     self.refresh_inventory(writer)?;
1035:                 } else {
1036:                     let mut fields = Vec::new();
1037:                     for value in [
1038:                         click.menu,
1039:                         i32::from(click.slot),
1040:                         i32::from(click.button),
1041:                         click.mode,
1042:                     ] {
1043:                         rusty_mines_inventory::wire::put_int(&mut fields, value);
1044:                     }
1045:                     self.queue_inventory(2, fields, Some(click), writer)?;
1046:                 }
1047:                 true
1048:             }
1049:             Ok(play::Serverbound::CloseContainer(menu)) => {
1050:                 self.inventory_reopen_menu = true;
1051:                 if self.inventory_pending.is_some() {
1052:                     self.inventory_deferred_close = Some(menu);
1053:                 } else {
1054:                     let mut fields = Vec::new();
1055:                     rusty_mines_inventory::wire::put_int(&mut fields, menu);
1056:                     self.queue_inventory(4, fields, None, writer)?;
1057:                 }
1058:                 true
1059:             }
1060:             Ok(
1061:                 play::Serverbound::Punch
1062:                 | play::Serverbound::RecipeSettings
1063:                 | play::Serverbound::PickBlock
1064:                 | play::Serverbound::PickEntity
1065:                 | play::Serverbound::Attack(_),
1066:             ) => true,
1067:             Err(_) => false,
1068:         };
1069:         if !valid {
1070:             return self.disconnect_play(
1071:                 writer,
1072:                 "Unsupported or invalid Play packet; static world only",
1073:             );
1074:         }
1075:         self.confirm_play(writer)
1076:     }
1312:     fn reset_loading(&mut self) {
1313:         self.loading_ticks = 0;
1314:         self.loading_started = Some((self.clock)());
1315:         self.player_loaded = false;
1316:         self.teleport_confirmed = false;
1317:         self.play_confirmed = false;
1318:         self.pending_teleport = None;
1319:     }
1355:     fn send_mode_state(&self, writer: &mut impl Write) -> io::Result<()> {
1356:         let flags = match self.game_mode {
1357:             1 => 0x0f, // Creative: invulnerable, flying, allowed to fly, instant build.
1358:             3 => 0x07, // Spectator: invulnerable, flying, and allowed to fly.
1359:             _ => 0,
1360:         };
1361:         play::Clientbound::Abilities {
1362:             flags,
1363:             flying_speed: 0.05,
1364:             walking_speed: 0.1,
1365:         }
1366:         .write(writer)?;
1367:         play::Clientbound::Health {
1368:             health: self.health,
1369:             food: self.food,
1370:             saturation: 5.0,
1371:         }
1372:         .write(writer)?;
1373:         play::Clientbound::GameEvent {
1374:             event: 3,
1375:             value: f32::from(self.game_mode),
1376:         }
1377:         .write(writer)?;
1378:         Ok(())
1379:     }
1381:     fn respawn(
1382:         &mut self,
1383:         expected: crate::gateway::GatewayPlayerState,
1384:         writer: &mut impl Write,
1385:     ) -> io::Result<()> {
1386:         if !self.dead || !matches!(self.game_mode, 0 | 2) {
1387:             return Ok(());
1388:         }
1389:         self.player_position = [8.5, 65.0, 8.5];
1390:         self.vertical_velocity = 0.0;
1391:         self.on_ground = true;
1392:         self.health = f32::from(expected.health);
1393:         self.food = i32::from(expected.food);
1394:         self.dead = false;
1395:         self.simulation_at = (self.clock)();
1396:         self.loaded_chunks.clear();
1397:         self.chunk_revisions.clear();
1398:         self.pending_chunk_center = Some((0, 0));
1399:         self.next_chunk_batch = self.simulation_at + SERVER_TICK;
1400:         self.inventory_snapshot = None;
1401:         self.inventory_resync = true;
1402:         self.inventory_pending = None;
1403:         self.inventory_deferred_close = None;
1404:         self.inventory_reopen_menu = false;
1405:         self.block_pending = None;
1406:         self.pending_mode = None;
1407:         self.pending_player_state = None;
1408:         self.dead = false;
1409:         self.sprinting = false;
1410:         self.flying = matches!(self.game_mode, 1 | 3);
1411:         self.next_food_drain = self.simulation_at + Duration::from_secs(5);
1412:         self.player_loaded = false;
1413:         self.loading_ticks = 0;
1414:         self.loading_started = Some(self.simulation_at);
1415:         play::Clientbound::Respawn {
1416:             adventure: self.game_mode == 2,
1417:         }
1418:         .write(writer)?;
1419:         self.send_mode_state(writer)?;
1420:         self.publish_authoritative_pose()?;
1421:         self.send_teleport(TeleportKind::Correction, writer)
1422:     }
1424:     fn simulate_vertical(&mut self, now: Instant, writer: &mut impl Write) -> io::Result<()> {
1425:         if self.game_mode == 3 || self.dead {
1426:             return Ok(());
1427:         }
1428:         let initial_y = self.player_position[1];
1429:         let elapsed = now.saturating_duration_since(self.simulation_at);
1430:         let ticks = (elapsed.as_nanos() / SERVER_TICK.as_nanos()).min(8) as u32;
1431:         if ticks == 0 {
1432:             return Ok(());
1433:         }
1434:         self.simulation_at += SERVER_TICK * ticks;
1435:         for _ in 0..ticks {
1436:             if self.flying && self.game_mode == 1 {
1437:                 self.vertical_velocity = 0.0;
1438:             } else {
1439:                 let was_above_platform = self.player_position[1] >= 65.0;
1440:                 self.vertical_velocity = (self.vertical_velocity - 0.08).max(-3.92);
1441:                 self.player_position[1] += self.vertical_velocity;
1442:                 if was_above_platform && self.player_position[1] <= 65.0 {
1443:                     self.player_position[1] = 65.0;
1444:                     self.vertical_velocity = 0.0;
1445:                     self.on_ground = true;
1446:                 } else {
1447:                     self.on_ground = false;
1448:                 }
1449:             }
1450:             if self.game_mode == 0 && self.sprinting && self.food > 0 && now >= self.next_food_drain
1451:             {
1452:                 self.food -= 1;
1453:                 self.next_food_drain = now + Duration::from_secs(5);
1454:                 play::Clientbound::Health {
1455:                     health: self.health,
1456:                     food: self.food,
1457:                     saturation: 5.0_f32.min(self.food as f32),
1458:                 }
1459:                 .write(writer)?;
1460:             }
1461:             if self.player_position[1] < -64.0 {
1462:                 if matches!(self.game_mode, 0 | 2) {
1463:                     if let Some(session) = self.backend_session {
1464:                         if self
1465:                             .pending_player_state
1466:                             .as_ref()
1467:                             .is_none_or(|pending| pending.expected.dead)
1468:                         {
1469:                             self.persist_player_state(now, false, writer)?;
1470:                         }
1471:                         match self.backend.player_state(session) {
