284: pub fn change_game_mode(
285:     ctx: &ReducerContext,
286:     session_uuid: Uuid,
287:     mode: GameMode,
288: ) -> Result<(), String> {
289:     let connection = foundation::require_gateway(ctx)?;
290:     let session = ctx
291:         .db
292:         .player_session()
293:         .session_uuid()
294:         .find(session_uuid)
295:         .ok_or("Session not found")?;
296:     if !foundation::owns_session(&session, ctx.sender(), connection) {
297:         return Err("Mode session belongs to another connection".into());
298:     }
299:     foundation::require_session_lease(ctx, &session)?;
300:     if session.phase != SessionPhase::Play {
301:         return Err("Mode changes require active Play".into());
302:     }
303:     if matches!(mode, GameMode::Creative | GameMode::Spectator) {
304:         return Err("Creative and Spectator must be granted by an administrator".into());
305:     }
306:     let vitals = ctx
307:         .db
308:         .player_vitals()
309:         .player_uuid()
310:         .find(session.player_uuid)
311:         .ok_or("Player vitals are unavailable")?;
312:     if vitals.connected_gateway != Some(ctx.sender())
313:         || vitals.connected_session != Some(session_uuid)
314:     {
315:         return Err("Player state is owned by another active session".into());
316:     }
317:     let row = PlayerGameMode {
318:         player_uuid: session.player_uuid,
319:         mode,
320:     };
321:     if ctx
322:         .db
323:         .player_game_mode()
324:         .player_uuid()
325:         .find(session.player_uuid)
326:         .is_some()
327:     {
328:         ctx.db.player_game_mode().player_uuid().update(row);
329:     } else {
330:         ctx.db.player_game_mode().insert(row);
331:     }
332:     Ok(())
333: }
